<?php
session_start();require_once __DIR__.'/koneksi.php';require_once __DIR__.'/includes/auth.php';require_once __DIR__.'/includes/legacy_operational_bank.php';require_once __DIR__.'/includes/legacy_ui.php';requireRole(['admin','kasir','bendahara']);
$error='';$notice='';$selected=null;$batch=$_GET['batch']??'';$search=$_GET['q']??'';$ownerId=filter_var($_GET['owner']??null,FILTER_VALIDATE_INT);$page=max(1,(int)($_GET['page']??1));$rows=[];$journals=[];$payments=[];$account=null;
if(!is_string($batch)||!preg_match('/^[a-f0-9]{32}$/D',$batch)||!is_string($search)||mb_strlen($search)>100){http_response_code(400);exit('Filter tidak valid.');}
if(empty($_SESSION['csrf_legacy_bank']))$_SESSION['csrf_legacy_bank']=bin2hex(random_bytes(32));
function lop_csv_row($stream,array $fields): void {foreach($fields as &$field)if(is_string($field)&&preg_match('/^[\s]*[=+@-]/u',$field))$field="'".$field;unset($field);fputcsv($stream,$fields);}
try{lop_require($koneksi);$b=lf_one($koneksi,"SELECT * FROM legacy_full_batches WHERE id=? AND state='completed'",[$batch]);if(!$b)throw new DomainException('Batch belum terverifikasi atau tidak ditemukan.',404);
    if($_SERVER['REQUEST_METHOD']==='POST'){if(!is_string($_POST['csrf_token']??null)||!hash_equals($_SESSION['csrf_legacy_bank'],$_POST['csrf_token']))throw new DomainException('Token CSRF tidak valid.',403);lop_bank_new($koneksi,(int)$_SESSION['admin_id'],unit_active_id(),(int)$ownerId,$_POST,(string)($_POST['request_key']??''));$notice='Transaksi tersimpan.';}
    $like='%'.$search.'%';$rows=lf_rows($koneksi,'SELECT o.*,g.label group_label,a.balance,a.opening FROM legacy_op_owners o LEFT JOIN legacy_op_groups g ON g.id=o.group_id AND g.unit_id=o.unit_id LEFT JOIN legacy_op_accounts a ON a.owner_id=o.id AND a.unit_id=o.unit_id WHERE o.batch_id=? AND (o.name LIKE ? OR o.source_identity LIKE ?) ORDER BY o.name LIMIT 25 OFFSET '.(($page-1)*25),[$batch,$like,$like]);
    if($ownerId)$selected=lf_one($koneksi,'SELECT * FROM legacy_op_owners WHERE id=? AND batch_id=?',[$ownerId,$batch]);
    if($selected){$account=lf_one($koneksi,'SELECT * FROM legacy_op_accounts WHERE owner_id=?',[$ownerId]);$journals=lf_rows($koneksi,"SELECT * FROM legacy_op_journals WHERE owner_id=? ORDER BY source_date,(origin='adjustment'),id",[$ownerId]);$payments=lf_rows($koneksi,'SELECT * FROM legacy_op_payments WHERE owner_id=? ORDER BY source_date,id',[$ownerId]);}
    if(($_GET['export']??'')==='csv'&&$selected){header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="rekening-legacy.csv"');$out=fopen('php://output','w');lop_csv_row($out,['Nama','Identitas sumber','Jenis','Tanggal','Masuk','Keluar','Total pembayaran','Status']);foreach($journals as $j)lop_csv_row($out,[$selected['name'],$selected['source_identity'],'Tabungan',$j['source_date'],$j['incoming'],$j['outgoing'],'',$j['cancelled']?'Dibatalkan':$j['origin']]);foreach($payments as $p)lop_csv_row($out,[$selected['name'],$selected['source_identity'],'Pembayaran',$p['source_date']??'Tanggal tidak tercatat','','',$p['total'],$p['cancelled']?'Dibatalkan':'Legacy']);exit;}
}catch(Throwable $e){http_response_code($e instanceof DomainException&&in_array($e->getCode(),[400,403,404],true)?$e->getCode():409);$error=$e instanceof DomainException?$e->getMessage():'Permintaan gagal. Data tetap disimpan.';}
function lae(mixed $v): string{return legacy_ui_e($v);}
?><!doctype html><html lang="id" data-palette="<?= unit_palette_for_view() ?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Rekening &amp; Transaksi Migrasi</title><link rel="stylesheet" href="assets/css/style.css"><link rel="stylesheet" href="assets/css/backup_restore.css"><link rel="stylesheet" href="assets/css/legacy_finance.css"><link rel="stylesheet" href="assets/css/legacy_ui.css"><link rel="stylesheet" href="assets/css/legacy_full.css"><script>document.documentElement.dataset.theme=localStorage.getItem('spp_theme')||'light';</script></head><body><div class="layout"><?php legacy_ui_sidebar(); ?><main class="main-content dbt-main"><div class="topbar"><h2>Rekening &amp; Transaksi Migrasi</h2></div><div class="db-tools-page legacy-ui"><h1>Data hasil migrasi</h1><?php if($error): ?><p class="dbt-warning" role="alert"><?= lae($error) ?></p><?php endif; ?><?php if($notice): ?><p class="dbt-info" role="status"><?= lae($notice) ?></p><?php endif; ?><section class="dbt-card"><form method="get"><input type="hidden" name="batch" value="<?= lae($batch) ?>"><label>Cari nama / identitas<input name="q" value="<?= lae($search) ?>"></label><button class="dbt-button">Cari</button></form><div class="dbt-table-scroll"><table class="dbt-table"><thead><tr><th>Nama</th><th>Kelompok</th><th>Jenis</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td><a href="?<?= lae(http_build_query(['batch'=>$batch,'q'=>$search,'page'=>$page,'owner'=>$row['id']])) ?>#rekening"><?= lae($row['name']) ?></a><br><?= lae($row['source_identity']) ?></td><td><?= lae($row['group_label']) ?></td><td><?= lae(['active'=>'Siswa aktif','psb'=>'PSB','out'=>'Siswa keluar','alumni'=>'Alumni','account'=>'Rekening khusus','legacy'=>'Perlu klasifikasi'][$row['kind']]) ?></td><td><?= $row['state']==='ready'?'Siap digunakan':'Perlu diperiksa' ?></td></tr><?php endforeach; ?></tbody></table></div><nav class="legacy-actions"><?php if($page>1): ?><a class="dbt-button" href="?<?= lae(http_build_query(['batch'=>$batch,'q'=>$search,'page'=>$page-1])) ?>">Sebelumnya</a><?php endif; ?><?php if(count($rows)===25): ?><a class="dbt-button" href="?<?= lae(http_build_query(['batch'=>$batch,'q'=>$search,'page'=>$page+1])) ?>">Berikutnya</a><?php endif; ?></nav></section>
<?php if($selected): ?><section class="dbt-card" id="rekening"><h2><?= lae($selected['name']) ?></h2><p><?= lae($selected['source_identity']) ?> · <?= lae($selected['source_class']) ?></p><?php if($account): ?><dl class="legacy-balance"><div><dt>Saldo sumber</dt><dd><?= lae(legacy_ui_money($account['source_balance'])) ?></dd></div><div><dt>Saldo peralihan saat ini</dt><dd><?= lae(legacy_ui_money($account['opening'])) ?></dd></div><div><dt>Saldo berjalan</dt><dd><?= lae(legacy_ui_money(lop_current_balance($koneksi,$selected,$account))) ?></dd></div></dl><?php else: ?><p class="dbt-warning">Saldo rekening ini belum disahkan. Tidak dianggap nol; rekening lain tetap dapat digunakan.</p><?php endif; ?><a class="dbt-button" href="?<?= lae(http_build_query(['batch'=>$batch,'owner'=>$ownerId,'export'=>'csv'])) ?>">Unduh Catatan CSV</a>
<?php if($account&&!$selected['student_id']&&$selected['state']==='ready'&&in_array($_SESSION['admin_role'],['super_admin','admin','kasir'],true)&&unit_active_id()!==0): ?><details><summary>Transaksi tabungan baru</summary><form method="post" class="lf-form"><input type="hidden" name="csrf_token" value="<?= lae($_SESSION['csrf_legacy_bank']) ?>"><input type="hidden" name="request_key" value="<?= bin2hex(random_bytes(32)) ?>"><label>Jenis<select name="direction"><option value="in">Setoran</option><option value="out">Penarikan</option></select></label><label>Nominal (Rp)<input name="amount" inputmode="decimal" required></label><label>Tanggal WIB<input type="datetime-local" name="date" required value="<?= date('Y-m-d\TH:i') ?>"></label><label>Catatan<textarea name="note" maxlength="1000"></textarea></label><button class="dbt-button dbt-button-primary">Simpan Transaksi</button></form></details><?php elseif($selected['student_id']): ?><p><a class="dbt-button" href="tabungan/masuk.php">Transaksi tabungan siswa</a></p><?php endif; ?>
<?php if($selected['student_id']&&unit_is_super()&&unit_active_id()!==0): ?><a class="dbt-button" href="legacy_tariff.php?student=<?= (int)$selected['student_id'] ?>">Ubah Dasar Tarif SPP</a><?php endif; ?><h3>Pembayaran</h3><div class="dbt-table-scroll"><table class="dbt-table"><thead><tr><th>Tanggal / periode</th><th>Nominal</th><th>Status</th><th>Tindakan</th></tr></thead><tbody><?php foreach($payments as $p): ?><tr><td><?= lae($p['source_date']?:'Tanggal tidak tercatat') ?><br><?= lae($p['source_period']) ?></td><td><?= lae(legacy_ui_money($p['total'])) ?></td><td><?= $p['cancelled']?'Dibatalkan':'Migrasi' ?></td><td><?php if(unit_is_super()&&unit_active_id()!==0): ?><a class="dbt-button" href="legacy_correction.php?kind=payment&amp;id=<?= (int)$p['id'] ?>">Koreksi</a><?php endif; ?> <a href="laporan/cetak_legacy.php?id=<?= 1000000000+(int)$p['id'] ?>&amp;unit_id=<?= (int)$selected['unit_id'] ?>">Cetak</a></td></tr><?php endforeach; ?></tbody></table></div>
<h3>Jurnal tabungan</h3><div class="dbt-table-scroll"><table class="dbt-table"><thead><tr><th>Tanggal</th><th>Masuk</th><th>Keluar</th><th>Saldo berjalan</th><th>Sumber / status</th><th>Tindakan</th></tr></thead><tbody><?php $runningJournal=0;foreach($journals as $j): if(!$j['cancelled'])$runningJournal+=lf_cents($j['incoming'])-lf_cents($j['outgoing']); ?><tr><td><?= lae($j['source_date']) ?></td><td><?= lae(legacy_ui_money($j['incoming'])) ?></td><td><?= lae(legacy_ui_money($j['outgoing'])) ?></td><td><?= lae(legacy_ui_money(lf_money($runningJournal))) ?></td><td><?= $j['cancelled']?'Dibatalkan':($j['origin']==='adjustment'?'Penyesuaian Saldo Migrasi':($j['origin']==='legacy'?'Legacy':'Transaksi baru')) ?></td><td><?php if(unit_is_super()&&unit_active_id()!==0): ?><a class="dbt-button" href="legacy_correction.php?kind=journal&amp;id=<?= (int)$j['id'] ?>">Koreksi</a><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php endif; ?></div></main></div><script src="assets/js/app.js"></script><script src="assets/js/legacy_ui.js"></script></body></html>
